mpi_lor.example_code:
call MPI_Allreduce(bad_local, any_bad, 1, MPI_LOGICAL, &
                   MPI_LOR, MPI_COMM_WORLD, ierr)
if (any_bad) call MPI_Abort(MPI_COMM_WORLD, 3, ierr)

mpi_success.example_code:
call MPI_Comm_set_errhandler(MPI_COMM_WORLD, MPI_ERRORS_RETURN, ierr)
call MPI_Send(buf, n, MPI_INTEGER, dest, tag, MPI_COMM_WORLD, ierr)
if (ierr /= MPI_SUCCESS) call handle_failure(ierr)
